focalisation_de_base_6&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_7&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_d’&#233;vocation_34&quot;&gt;Instruments d’&#233;vocation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_8&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_9&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_10&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_11&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_d’illusion_35&quot;&gt;Instruments d’illusion&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_12&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_13&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_14&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_15&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_d’invocation_36&quot;&gt;Instruments d’invocation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_16&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_17&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_18&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_19&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_de_divination_37&quot;&gt;Instruments de divination&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_20&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_21&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_22&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_23&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_de_n&#233;cromancie_38&quot;&gt;Instruments de n&#233;cromancie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_24&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_25&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_26&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_27&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_de_transmutation_39&quot;&gt;Instruments de transmutation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Instruments_28&quot;&gt;Instruments&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_r&#233;sonance_29&quot;&gt;Pouvoir de r&#233;sonance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoir_de_focalisation_de_base_30&quot;&gt;Pouvoir de focalisation de base&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_focalisation_31&quot;&gt;Pouvoirs de focalisation&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
Les occultistes choisissent leurs &#233;coles instrumentales, dont chacune repr&#233;sente une &#233;cole de magie, parmi celles de la liste suivante. Un occultiste peut choisir une &#233;cole instrumentale plusieurs fois, comme indiqu&#233; dans la description de l’aptitude de classe instruments.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABJURATION&quot; href=&quot;#ABJURATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments d’abjuration&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_d’abjuration_32&quot; href=&quot;#Instruments_d’abjuration_32&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments d’abjuration sont des objets associ&#233;s &#224; la protection et &#224; la pr&#233;vention.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABJURATIONINSTRUMENTS&quot; href=&quot;#ABJURATIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_0&quot; href=&quot;#Instruments_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Amulette, armure, bouclier, brassard, broche, cape, cloche, symbole sacr&#233;.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABJURATIONRESONANCE&quot; href=&quot;#ABJURATIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_1&quot; href=&quot;#Pouvoir_de_r&#233;sonance_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument d’abjuration, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Talisman de protection (Sur)&lt;/i&gt; L’instrument offre une protection contre les effets adverses. Quiconque le porte (ou le tient dans le cas d’une cloche, par exemple) b&#233;n&#233;ficie d’un bonus de r&#233;sistance de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; pour chaque tranche de 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’instrument, jusqu’&#224; un bonus maximum de 1 + 1 tous les 4 niveaux d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABJURATIONFOCALISATIONDEBASE&quot; href=&quot;#ABJURATIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_2&quot; href=&quot;#Pouvoir_de_focalisation_de_base_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments d’abjuration acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Barri&#232;re d’&#233;nergie spirituelle (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour lever une barri&#232;re d’&#233;nergie mentale autour de lui qui le prot&#232;ge des coups. La barri&#232;re absorbe un total de 2 points de d&#233;g&#226;ts par niveau d’occultiste. Elle reste en place jusqu’au d&#233;but de son prochain tour ou jusqu’&#224; &#233;puisement de sa capacit&#233; d’absorption. Par exemple, un occultiste de niveau 5 peut lever une barri&#232;re mentale capable d’absorber 10 points de d&#233;g&#226;ts. S’il est touch&#233; par une attaque qui devrait lui infliger 12 points de d&#233;g&#226;ts, la barri&#232;re mentale est &#233;puis&#233;e et le personnage subit 2 points de d&#233;g&#226;ts. Le personnage peut activer ce pouvoir par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; en d&#233;pensant 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; au lieu d’un seul.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABJURATIONFOCALISATION&quot; href=&quot;#ABJURATIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_3&quot; href=&quot;#Pouvoirs_de_focalisation_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments d’abjuration peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe pouvoirs de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Dissolution (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour dissoudre un effet magique. Ce pouvoir fonctionne comme une dissipation de la magie cibl&#233;e mais le personnage doit &#234;tre adjacent &#224; l’effet qu’il souhaite dissoudre. Si l’effet est cr&#233;&#233; par l’utilisation de la &lt;a class=&quot;pagelink&quot; href=&quot;La-Magie-Psychique.html&quot; title=&quot;La magie psychique&quot;&gt;magie psychique&lt;/a&gt;, le personnage b&#233;n&#233;ficie d’un bonus de +5 au test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; effectu&#233; pour le dissoudre. Si l’effet cible un objet poss&#233;d&#233; par le personnage, celui-ci r&#233;ussit automatiquement le test. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt; &#201;cran contre les &#233;nergies destructives (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour s’entourer d’un &#233;cran qui le prot&#232;ge des d&#233;g&#226;ts d’&#233;nergie destructive. Chaque fois qu’il subit des d&#233;g&#226;ts d’acide, d’&#233;lectricit&#233;, de feu ou de froid, l’&#233;cran absorbe les d&#233;g&#226;ts (comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;). L’&#233;cran peut absorber jusqu’&#224; 5 points de d&#233;g&#226;ts d’&#233;nergie destructive par niveau d’occultiste. Cet &#233;cran reste en place pendant 1 minute ou jusqu’&#224; &#233;puisement de sa capacit&#233; d’absorption. Ses effets ne se cumulent pas entre eux, ni avec ceux d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; ou d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;. Le personnage peut activer ce pouvoir par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; en d&#233;pensant 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; au lieu d’un seul. Il doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;&#201;gide (Sur).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; et toucher une armure ou un bouclier pour lui conf&#233;rer un bonus d’alt&#233;ration. Ce bonus est &#233;gal &#224; 1 + 1 tous les 6 niveaux d’occultiste (jusqu’&#224; un bonus maximum de +4 au niveau 18). Les bonus d’alt&#233;ration obtenus gr&#226;ce &#224; ce pouvoir se cumulent avec ceux de l’armure ou du bouclier, jusqu’&#224; un total maximum de +5. Le personnage peut &#233;galement conf&#233;rer &#224; l’armure ou au bouclier une propri&#233;t&#233; sp&#233;ciale dont l’&#233;quivalent pour le bonus d’alt&#233;ration est inf&#233;rieur ou &#233;gal au bonus maximal que le personnage peut conf&#233;rer &#224; l’arme. Ce faisant, il diminue le bonus d’alt&#233;ration conf&#233;r&#233; du montant de la propri&#233;t&#233; sp&#233;ciale. L’objet doit poss&#233;der un bonus d’alt&#233;ration de +1 au moins (ce bonus doit provenir de l’objet lui-m&#234;me ou de l’&#233;gide) pour pouvoir b&#233;n&#233;ficier d’une propri&#233;t&#233; sp&#233;ciale d’armure ou de bouclier. Ces bonus et l’&#233;ventuelle propri&#233;t&#233; sp&#233;ciale durent une minute.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Globe de n&#233;gation (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 3 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er un globe de n&#233;gation immobile. Ce globe mesure 3 m&#232;tres de diam&#232;tre et annule tous les effets de sorts lanc&#233;s vers l’int&#233;rieur ou au travers de la zone qu’il d&#233;limite. Il fonctionne comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Globe-Dinvuln&#233;rabilit&#233;-Partielle.html&quot; title=&quot;Globe d&amp;#39;invuln&#233;rabilit&#233; partielle&quot;&gt;globe d’invuln&#233;rabilit&#233;&lt;/a&gt;&lt;/i&gt; mais affecte tous les sorts, quel que soit leur niveau. Le globe peut annuler un nombre total de niveaux de sort &#233;gal au niveau d’occultiste du personnage avant de se d&#233;sagr&#233;ger. Les sorts qui d&#233;passent le nombre de niveaux restants &#233;liminent tous ces niveaux mais voient leur puissance affaiblie ; les cr&#233;atures cibl&#233;es par ces sorts b&#233;n&#233;ficient d’un bonus de circonstances de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; effectu&#233;s contre leurs effets. Le globe reste en place pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au niveau d’occultiste du personnage. Il n’a aucun effet sur les sorts lanc&#233;s depuis l’int&#233;rieur de sa zone mais seulement sur ceux qui p&#233;n&#232;trent dans sa zone au moment de leur incantation ou apr&#232;s celle-ci. Le personnage doit avoir atteint le niveau 11 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Protection planaire (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er une protection planaire autour de lui. Les cr&#233;atures qui ne sont pas natives du plan sur lequel se trouve le personnage subissent un malus de -4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; effectu&#233;s contre lui et le personnage b&#233;n&#233;ficie d’un bonus de circonstances de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; effectu&#233;s contre les sorts, les pouvoirs magiques et les pouvoirs surnaturels de ces cr&#233;atures. Cette protection reste en place pendant une minute.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Sentinelle de site (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour placer une sentinelle de surveillance dans une zone. Le rayon maximum de cette zone s’&#233;l&#232;ve &#224; 3 m&#232;tres + 1,50 m&#232;tre par niveau d’occultiste. Chaque fois qu’une cr&#233;ature entre dans cette zone, une sentinelle cr&#233;&#233;e par la psych&#233; du personnage appara&#238;t et s’en prend &#224; l’intrus. La cr&#233;ature affect&#233;e doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour ne pas &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#H&#233;b&#233;t&#233;.html&quot; title=&quot;H&#233;b&#233;t&#233;&quot;&gt;h&#233;b&#233;t&#233;e&lt;/a&gt; pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Le personnage est imm&#233;diatement averti de l’activation de sa sentinelle. Celle-ci reste en place pendant une dur&#233;e maximale d’une heure par niveau d’occultiste ou jusqu’&#224; son d&#233;clenchement. Quand le personnage place la sentinelle, il peut d&#233;signer n’importe quel nombre de cr&#233;atures sp&#233;cifiques qui seront immunis&#233;es &#224; l’effet de ce pouvoir et ne le d&#233;clencheront donc pas.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENCHANTEMENT&quot; href=&quot;#ENCHANTEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments d’enchantement&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_d’enchantement_33&quot; href=&quot;#Instruments_d’enchantement_33&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments d’enchantement permettent aux occultistes de brouiller les esprits et de charmer leurs ennemis.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENCHANTEMENTINSTRUMENTS&quot; href=&quot;#ENCHANTEMENTINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_4&quot; href=&quot;#Instruments_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Collier, couronne, encensoir, heaume, instrument de musique.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENCHANTEMENTRESONANCE&quot; href=&quot;#ENCHANTEMENTRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_5&quot; href=&quot;#Pouvoir_de_r&#233;sonance_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument d’enchantement, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Pr&#233;sence resplendissante (Sur)&lt;/i&gt;. L’instrument invoque la pr&#233;sence de ceux qui l’ont port&#233; par le pass&#233;. Son porteur b&#233;n&#233;ficie d’un bonus de comp&#233;tence de +1 aux tests de comp&#233;tence bas&#233;es sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour chaque tranche de 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’instrument, jusqu’&#224; un maximum de 1 + 1 tous les 4 niveaux d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENCHANTEMENTFOCALISATIONDEBASE&quot; href=&quot;#ENCHANTEMENTFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_6&quot; href=&quot;#Pouvoir_de_focalisation_de_base_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments d’enchantement acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Esprit troubl&#233; (Sur).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour troubler l’esprit d’un ennemi situ&#233; &#224; 9 m&#232;tres ou moins. Cet ennemi est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#H&#233;b&#233;t&#233;.html&quot; title=&quot;H&#233;b&#233;t&#233;&quot;&gt;h&#233;b&#233;t&#233;&lt;/a&gt; pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; si son nombre de D&#233;s de Vie est inf&#233;rieur ou &#233;gal au niveau d’occultiste du personnage. Dans le cas contraire, il n’est que &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelant&lt;/a&gt; pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. L’ennemi peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Qu’il r&#233;ussisse ou non ce jet, il est ensuite immunis&#233; &#224; cet effet pendant une journ&#233;e. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENCHANTEMENTFOCALISATION&quot; href=&quot;#ENCHANTEMENTFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_7&quot; href=&quot;#Pouvoirs_de_focalisation_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments d’enchantement peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Agression inspir&#233;e (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut inspirer une cr&#233;ature vivante d’un simple contact en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. La cr&#233;ature b&#233;n&#233;ficie alors d’un bonus de moral aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; &#233;gal &#224; 1 + 1 tous les 6 niveaux d’occultiste (jusqu’&#224; un bonus maximal de +4 au niveau 18). Ce bonus s’applique &#233;galement aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets de terreur et dure une minute.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Alliance contrainte (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut modifier l’&#233;tat d’esprit d’une cr&#233;ature vivante pour la forcer &#224; le consid&#233;rer comme un ami et un alli&#233;. Si la cr&#233;ature est du m&#234;me type que le personnage, celui-ci doit d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; ; sinon, il doit en d&#233;penser 2. La cr&#233;ature peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler cet effet. Si elle rate ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;, elle consid&#232;re le personnage comme un alli&#233; et n’essaye pas de le blesser (les alli&#233;s du personnage ne sont toutefois pas prot&#233;g&#233;s). Le personnage peut demander &#224; la cr&#233;ature de l’aider directement mais, dans ce cas, elle peut effectuer un nouveau jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; &#224; la fin de chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; pour mettre fin &#224; l’effet. Cet effet dure par ailleurs un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; de charme. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Entrave psychique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er une entrave d’&#233;nergie psychique qui provoque la paralysie d’une cr&#233;ature vivante. La cible doit &#234;tre situ&#233;e &#224; 9 m&#232;tres ou moins du personnage et peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Si elle rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;, elle reste &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralys&#233;e&lt;/a&gt; pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; tous les 2 niveaux d’occultiste. &#192; la fin de chacun de ses tours, elle peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour mettre fin &#224; la paralysie et &#234;tre simplement &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelante&lt;/a&gt; pendant toute la dur&#233;e restante. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; de coercition. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Ob&#233;issance (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut donner un ordre &#224; une cr&#233;ature vivante en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. Cet effet fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction.html&quot; title=&quot;Injonction&quot;&gt;injonction&lt;/a&gt;&lt;/i&gt;. La cible doit &#234;tre situ&#233;e &#224; 9 m&#232;tres ou moins et doit comprendre l’ordre donn&#233; par le personnage. Elle peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Si la cr&#233;ature est du m&#234;me type que le personnage, elle subit un malus de -2 &#224; ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Somnolence de l’esprit (Mag)&lt;/i&gt;. En d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut endormir une cr&#233;ature vivante et la plonger dans un profond sommeil mental afin de l’obliger &#224; voir le monde comme dans un r&#234;ve. La cible doit &#234;tre situ&#233;e &#224; 9 m&#232;tres ou moins et peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Si elle rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;, elle s’endort mais continue de percevoir son environnement comme dans un r&#234;ve. La cr&#233;ature ne tombe pas &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#192;terre.html&quot; title=&quot;&#192; terre&quot;&gt;&#224; terre&lt;/a&gt; pour autant mais l&#226;che tout ce qu’elle tient en main. Elle ne peut entreprendre aucune action tant qu’elle est dans cet &#233;tat mais n’est pas &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Sansd&#233;fense.html&quot; title=&quot;Sans d&#233;fense&quot;&gt;sans d&#233;fense&lt;/a&gt; et continue de percevoir le danger m&#234;me si elle r&#234;ve. La cr&#233;ature reste endormie pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au niveau d’occultiste du personnage ou jusqu’&#224; ce qu’elle subisse le moindre d&#233;g&#226;t, ce qui la r&#233;veille imm&#233;diatement. &#192; la fin de chacun de ses tours, elle peut effectuer un nouveau jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour mettre fin &#224; l’effet. La cr&#233;ature peut &#234;tre manipul&#233;e ou examin&#233;e sans la r&#233;veiller mais il est impossible de la d&#233;placer hors de la case qu’elle occupe sans la r&#233;veiller. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; de coercition. Qu’elle r&#233;ussisse son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; ou non, la cible est ensuite immunis&#233;e &#224; cet effet pendant 24 heures. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Trouble mental (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour perturber l’esprit d’une cr&#233;ature vivante situ&#233;e &#224; 9 m&#232;tres ou moins. La cr&#233;ature peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Si elle rate son jet, elle ne peut plus se concentrer sur ses effets magiques et doit r&#233;ussir un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#CONCENTRATION&quot; title=&quot;Lancer des sorts&quot;&gt;test de concentration&lt;/a&gt; pour lancer un sort (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 15 + deux fois le niveau du sort). La cr&#233;ature affect&#233;e subit un malus de -4 &#224; ce test si le sort n&#233;cessite une composante intellectuelle. La cr&#233;ature subit un malus de -2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pendant toute la dur&#233;e de cet effet qui dure un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVOCATION&quot; href=&quot;#EVOCATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments d’&#233;vocation&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_d’&#233;vocation_34&quot; href=&quot;#Instruments_d’&#233;vocation_34&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments d’&#233;vocation permettent aux occultistes de cr&#233;er et de manipuler des &#233;nergies dans un but d&#233;fensif ou offensif.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVOCATIONINSTRUMENTS&quot; href=&quot;#EVOCATIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_8&quot; href=&quot;#Instruments_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Baguette, b&#226;ton, gant, sceptre.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVOCATIONRESONANCE&quot; href=&quot;#EVOCATIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_9&quot; href=&quot;#Pouvoir_de_r&#233;sonance_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument d’&#233;vocation, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Focalisation intensifi&#233;e (Sur)&lt;/i&gt;. L’instrument canalise et augmente les effets de la magie d’&#233;vocation destructrice. Un lanceur de sorts en possession de l’instrument peut l’ajouter en guise de composante de focalisation suppl&#233;mentaire &#224; ses sorts d’&#233;vocation ou ses pouvoirs de focalisation qui infligent des d&#233;g&#226;ts et dont la dur&#233;e est instantan&#233;e. Le cas &#233;ch&#233;ant, le sort ou le pouvoir de focalisation inflige 1 point de d&#233;g&#226;ts suppl&#233;mentaire du m&#234;me type &#224; chaque cr&#233;ature pour chaque tranche de 2 points de focalisation investis dans l’instrument, jusqu’&#224; un maximum de 1 + 1 tous les 2 niveaux d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVOCATIONFOCALISATIONDEBASE&quot; href=&quot;#EVOCATIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt; 	
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_10&quot; href=&quot;#Pouvoir_de_focalisation_de_base_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 	
Tous les occultistes qui apprennent l’utilisation des instruments d’&#233;vocation acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Rayon d’&#233;nergie destructive (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; qui provoque des attaques d’opportunit&#233;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; &#224; distance sous la forme d’un rayon d’&#233;nergie pure. Ce rayon a une port&#233;e de 9 m&#232;tres et inflige un nombre de points de d&#233;g&#226;ts &#233;gal &#224; 1d6 + 1d6 tous les 2 niveaux d’occultiste au-del&#224; du premier (2d6 au niveau 3, 3d6 au niveau 5, et ainsi de suite, jusqu’&#224; un maximum de 10d6 au niveau 19). Le personnage doit d&#233;terminer le type de d&#233;g&#226;ts inflig&#233;s quand il tire un rayon d’&#233;nergie destructive (acide, &#233;lectricit&#233;, feu ou froid).&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVOCATIONFOCALISATION&quot; href=&quot;#EVOCATIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_11&quot; href=&quot;#Pouvoirs_de_focalisation_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments d’&#233;vocation peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Brillance (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut toucher une arme pour provoquer son illumination en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. L’arme &#233;met alors une lumi&#232;re &#233;quivalente &#224; celle d’une torche. En ce qui concerne les sorts et les pouvoirs de t&#233;n&#232;bres, on consid&#232;re cet effet comme un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt; de niveau 0, plus 1 niveau de sort suppl&#233;mentaire par tranche de 2 niveaux d’occultiste. L’arme continue de briller pendant une minute par niveau d’occultiste. De plus, chaque fois que l’arme inflige un coup critique contre un adversaire, la cr&#233;ature qui la manie peut d&#233;cider de mettre fin &#224; l’effet pour cerner l’adversaire de lumi&#232;re pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. La cible illumin&#233;e de la sorte ne peut profiter d’aucun camouflage ni d’aucun effet d’invisibilit&#233; et ne peut plus effectuer de tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; pour &#233;viter qu’on la rep&#232;re. Tous les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; effectu&#233;s contre un adversaire illumin&#233; b&#233;n&#233;ficient d’un bonus de circonstances de +2.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Explosion d’&#233;nergie destructive (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; qui provoque des attaques d’opportunit&#233;, le personnage peut d&#233;penser 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour d&#233;clencher une explosion d’&#233;nergie destructive. Cette explosion a une port&#233;e de 30 m&#232;tres et inflige 5d6 points de d&#233;g&#226;ts d’&#233;nergie destructive, plus 1d6 points de d&#233;g&#226;ts suppl&#233;mentaires tous les 2 niveaux d’occultiste au-del&#224; du cinqui&#232;me (6d6 au niveau 7, 7d6 au niveau 9, et ainsi de suite, jusqu’&#224; un maximum de 12d6 au niveau 19). L’explosion inflige des d&#233;g&#226;ts &#224; chaque cr&#233;ature situ&#233;e dans un rayonnement de 6 m&#232;tres de rayon mais chaque cr&#233;ature affect&#233;e peut effectuer un jet de R&#233;flexes pour diminuer les d&#233;g&#226;ts de moiti&#233;. Le personnage doit d&#233;terminer le type de d&#233;g&#226;ts inflig&#233;s quand il d&#233;clenche une explosion d’&#233;nergie destructive (acide, &#233;lectricit&#233;, feu ou froid). Il doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Fa&#231;onnage des zones d’effet (Sur)&lt;/i&gt;. Lors de l’incantation d’un sort d’&#233;vocation &#224; zone d’effet, le personnage peut d&#233;penser un nombre variable de points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; (ce nombre ne peut pas d&#233;passer son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;) pour exclure ce m&#234;me nombre de cases de la zone d’effet du sort lanc&#233;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Matrice lumineuse (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er un orbe de lumi&#232;res tourbillonnantes qui ob&#233;it &#224; ses ordres. Cet orbe illumine les alentours comme un sort de lumi&#232;re. Le personnage peut lui donner l’ordre de le suivre en l&#233;vitant au-dessus de son &#233;paule. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, il peut le diriger et le d&#233;placer sans l’&#233;loigner &#224; plus de 9 m&#232;tres de sa position. Si la matrice lumineuse se trouve &#224; plus de 9 m&#232;tres du personnage, elle revient l&#233;viter au-dessus de son &#233;paule. Si le personnage est de niveau 5 au moins, il peut diriger l’orbe pour qu’il effectue une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps contre un adversaire situ&#233; &#224; 9 m&#232;tres ou moins. Si l’attaque touche, la cible doit r&#233;ussir un jet de Vigueur pour ne pas &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugl&#233;e&lt;/a&gt; pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par le brusque &#233;clat de lumi&#232;re. Si l’attaque touche, que la cible ait r&#233;ussi son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; ou non, la matrice lumineuse dispara&#238;t imm&#233;diatement. Sinon, elle demeure pendant une heure par niveau d’occultiste. Celui-ci ne peut maintenir plusieurs matrices lumineuses actives en m&#234;me temps. S’il utilise ce pouvoir &#224; nouveau, la matrice lumineuse pr&#233;c&#233;dente dispara&#238;t imm&#233;diatement.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Mur de puissance (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;, le personnage peut cr&#233;er un mur d’&#233;nergie pure d’une longueur de 1,50 m&#232;tre par niveau d’occultiste. Ce mur mesure 3 m&#232;tres de haut et 30 centim&#232;tres d’&#233;paisseur. Il ne bloque pas le passage, les lignes de mire ou les lignes d’effet, mais il inflige des d&#233;g&#226;ts &#224; quiconque le traverse. Il inflige 2d6 points de d&#233;g&#226;ts d’&#233;nergie destructive + 1 point d’&#233;nergie destructive par niveau d’occultiste. Le personnage doit choisir l’acide, l’&#233;lectricit&#233;, le feu ou le froid au moment o&#249; il cr&#233;e le mur pour d&#233;terminer le type de d&#233;g&#226;ts que celui-ci inflige. Le mur doit &#234;tre droit et ne peut &#234;tre pos&#233; dans les cases occup&#233;es par des cr&#233;atures au moment de sa cr&#233;ation. Il reste en place pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage doit avoir atteint le niveau 9 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Protection des &#233;nergies (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour s’entourer d’un tourbillon d’&#233;nergie protectrice. Au moment o&#249; il active ce pouvoir, il doit choisir l’acide, l’&#233;lectricit&#233;, le feu ou le froid. Il gagne une r&#233;sistance de 10 contre le type d’&#233;nergie destructive choisi et, chaque fois qu’une cr&#233;ature le touche avec une arme de corps &#224; corps ou une arme naturelle, celle-ci subit 1d6 points de d&#233;g&#226;ts de ce type d’&#233;nergie. Les cr&#233;atures qui effectuent des attaques avec des armes de corps &#224; corps &#224; allonge ne subissent pas ces d&#233;g&#226;ts. Aux niveaux 13 et 19, la r&#233;sistance conf&#233;r&#233;e par cette protection augmente de 5 points, jusqu’&#224; une r&#233;sistance maximale de 20 au niveau 19. La protection des &#233;nergies dure un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ILLUSION&quot; href=&quot;#ILLUSION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments d’illusion&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_d’illusion_35&quot; href=&quot;#Instruments_d’illusion_35&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments d’illusion permettent aux occultistes de tromper les sens et de camoufler des cr&#233;atures.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ILLUSIONINSTRUMENTS&quot; href=&quot;#ILLUSIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_12&quot; href=&quot;#Instruments_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Anneau, couvre-chef, cristal, masque, prisme.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ILLUSIONRESONANCE&quot; href=&quot;#ILLUSIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_13&quot; href=&quot;#Pouvoir_de_r&#233;sonance_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument d’illusion, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Distorsion (Mag).&lt;/i&gt; L’instrument permet &#224; son porteur de distordre la perception de sa forme et de sa position pour le prot&#233;ger des coups. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le porteur peut b&#233;n&#233;ficier d’un camouflage pour que les attaques port&#233;es contre lui aient une chance de rater. Cette chance est &#233;gale &#224; 5 % par point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investi dans l’instrument (jusqu’&#224; un maximum de 5 % + 5 % tous les 2 niveaux d’occultiste) et persiste jusqu’&#224; la prochaine attaque du porteur. Cette chance de rater ne peut &#234;tre sup&#233;rieure &#224; 50 % mais, si elle devrait normalement d&#233;passer cette limite, le porteur b&#233;n&#233;ficie de tous les avantages d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;. Les cr&#233;atures dot&#233;es d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt; ou de pouvoirs similaires ignorent les chances de rater conf&#233;r&#233;es par ce pouvoir.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ILLUSIONFOCALISATIONDEBASE&quot; href=&quot;#ILLUSIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_14&quot; href=&quot;#Pouvoir_de_focalisation_de_base_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments d’illusion acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Chim&#232;re mineure (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er une chim&#232;re mineure. Celle-ci fonctionne comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Son-Imaginaire.html&quot; title=&quot;Son imaginaire&quot;&gt;son imaginaire&lt;/a&gt;&lt;/i&gt; ou une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Imparfaite.html&quot; title=&quot;Image imparfaite&quot;&gt;image imparfaite&lt;/a&gt;&lt;/i&gt;. Quel que soit l’effet choisi, il dure un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au niveau d’occultiste. Si l’occultiste est de niveau 7 ou plus, la chim&#232;re dure un nombre de minutes &#233;gal au niveau d’occultiste et le personnage peut modifier une fois la chim&#232;re au cours de sa dur&#233;e lorsqu’une circonstance sp&#233;cifi&#233;e survient.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ILLUSIONFOCALISATION&quot; href=&quot;#ILLUSIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_15&quot; href=&quot;#Pouvoirs_de_focalisation_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments d’illusion peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Cr&#233;ature d’ombre (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut convoquer une ou plusieurs cr&#233;atures compos&#233;es d’ombre en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. Ce pouvoir fonctionne comme une convocation d’ombres mais reproduit les effets des sorts de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres.html&quot; title=&quot;Convocation de monstres&quot;&gt;convocation de monstres&lt;/a&gt;&lt;/i&gt; uniquement. Les cr&#233;atures cr&#233;&#233;es &#224; l’aide de ce pouvoir infligent 50 % de leurs d&#233;g&#226;ts normaux sur ceux qui ne croient pas en l’illusion. Les effets qu’elles produisent et qui n’infligent pas de d&#233;g&#226;ts ont 50 % de chances seulement d’affecter avec succ&#232;s les cibles conscientes de la tromperie. Le personnage peut utiliser ce pouvoir pour reproduire n’importe quel sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres.html&quot; title=&quot;Convocation de monstres&quot;&gt;convocation de monstres&lt;/a&gt;&lt;/i&gt; jusqu’&#224; la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-V.html&quot; title=&quot;Convocation de monstres V&quot;&gt;convocation de monstres V&lt;/a&gt;&lt;/i&gt;. Pour chaque tranche de 2 niveaux d’occultiste au-del&#224; du 9&#232;me, le niveau du sort maximum qu’il peut reproduire en utilisant ce pouvoir augmente de 1 (jusqu’&#224; la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ix.html&quot; title=&quot;Convocation de monstres IX&quot;&gt;convocation de monstres IX&lt;/a&gt;&lt;/i&gt; au niveau 17). Quel que soit le sort reproduit, les cr&#233;atures agissent pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage doit avoir atteint le niveau 9 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Faisceau de couleurs (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour projeter un faisceau de couleurs changeantes sur une cible situ&#233;e &#224; 9 m&#232;tres ou moins. Le personnage doit effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; &#224; distance. Si le faisceau touche sa cible, celle-ci est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugl&#233;e&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; si son nombre de D&#233;s de Vie est &#233;gal ou inf&#233;rieur au niveau d’occultiste du personnage. Une cible avec un nombre de D&#233;s de Vie sup&#233;rieur est &#233;blouie pendant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; seulement. Elle peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Que ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; soit r&#233;ussi ou non, elle est ensuite immunis&#233;e &#224; cet effet pendant une journ&#233;e. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; d’illusion.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Image de d&#233;guisement (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour camoufler son apparence derri&#232;re une illusion, comme avec un d&#233;guisement. L’effet dure une minute par niveau d’occultiste. Au niveau 5, le personnage peut d&#233;penser 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; au lieu d’un seul pour prendre l’apparence d’une cr&#233;ature d’un type diff&#233;rent du sien mais dont la taille reste la m&#234;me que la sienne. Au niveau 7, il peut d&#233;penser 1 point de focalisation mentale suppl&#233;mentaire pour cibler une cr&#233;ature consentante au lieu de lui-m&#234;me avec ce pouvoir.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Invisibilit&#233; (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour devenir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisible&lt;/a&gt; comme avec une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;. Cet effet dure une minute par niveau d’occultiste. Le personnage peut d&#233;penser 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; au lieu d’un seul pour utiliser ce pouvoir sur une cr&#233;ature adjacente et consentante et non sur lui-m&#234;me. Il peut toujours voir les cr&#233;atures qu’il rend &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisibles&lt;/a&gt; avec ce pouvoir. Si la cr&#233;ature invisible effectue une attaque ou entreprend par ailleurs une action susceptible de mettre fin &#224; l’invisibilit&#233;, le personnage peut imm&#233;diatement d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; suppl&#233;mentaire pour que la cr&#233;ature, si elle se situe &#224; 9 m&#232;tres ou moins de lui, reste &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisible&lt;/a&gt;. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Mascarade (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour prendre l’apparence d’une cr&#233;ature qu’il est en train de toucher. Si la cr&#233;ature n’est pas amicale envers lui, le personnage doit r&#233;ussir une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps mais la cible ne peut effectuer aucun &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; pour annuler l’effet. Le personnage b&#233;n&#233;ficie d’un bonus de circonstances aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; &#233;gal &#224; son niveau d’occultiste + 10 mais uniquement pour ressembler &#224; la cr&#233;ature touch&#233;e. Ce bonus ne se cumule pas avec ceux conf&#233;r&#233;s par des sorts de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; ou autres effets similaires. Pendant la dur&#233;e de ce pouvoir, le personnage peut changer son aspect par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; en touchant une cr&#233;ature diff&#233;rente pour endosser son apparence. Il peut mettre fin &#224; cet effet quand il le souhaite. Sinon, il dure dix minutes par niveau d’occultiste mais il peut renouveler la dur&#233;e quand il le souhaite en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; suppl&#233;mentaire. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Mirage (Mag).&lt;/i&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour recouvrir une zone d’une illusion qui change son aspect. Le personnage peut affecter une zone &#233;quivalente &#224; un cube de 1,50 m&#232;tre d’ar&#234;te par niveau d’occultiste au maximum et changer son aspect qui doit toutefois para&#238;tre naturel compar&#233; aux environs, &#224; l’appr&#233;ciation du MJ. Le personnage peut, par exemple, cacher une porte ou un passage, faire appara&#238;tre de la nourriture illusoire sur une table ou cr&#233;er l’illusion d’une fosse. Il ne peut pas rendre invisible des cr&#233;atures ou des objets mais il peut modifier l’aspect d’un objet ou cr&#233;er une illusion derri&#232;re laquelle des cr&#233;atures peuvent se cacher. Ce pouvoir fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Accomplie.html&quot; title=&quot;Image accomplie&quot;&gt;image accomplie&lt;/a&gt;&lt;/i&gt; et les cr&#233;atures qui interagissent physiquement avec l’illusion de quelque mani&#232;re que ce soit peuvent effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour voir &#224; travers le mirage. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATION&quot; href=&quot;#INVOCATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments d’invocation&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_d’invocation_36&quot; href=&quot;#Instruments_d’invocation_36&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments d’invocation permettent aux occultistes d’accomplir une magie qui d&#233;place ou appelle des cr&#233;atures.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONINSTRUMENTS&quot; href=&quot;#INVOCATIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_16&quot; href=&quot;#Instruments_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Boussole, brasero, coupe, lanterne, miroir, statuette.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONRESONANCE&quot; href=&quot;#INVOCATIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_17&quot; href=&quot;#Pouvoir_de_r&#233;sonance_17&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument d’invocation, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Focalisation des incantations (Sur)&lt;/i&gt;. L’instrument intensifie les liens de son porteur avec les mondes ext&#233;rieurs et permet de maintenir plus longtemps l’effet de ses sorts. Le porteur peut ajouter l’instrument en guise de composante de focalisation suppl&#233;mentaire &#224; un sort d’invocation qu’il lance et dont la dur&#233;e se mesure en &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par niveau. Ce faisant, il augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; de 1 par tranche de 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’instrument (jusqu’&#224; un bonus maximal &#233;gal au niveau d’occultiste). Cette augmentation s’applique uniquement pour d&#233;terminer la dur&#233;e du sort et apr&#232;s l’application d’autres effets qui modifient cette dur&#233;e, comme le don &lt;a class=&quot;pagelink&quot; href=&quot;Extension-De-Dur&#233;e.html&quot; title=&quot;Extension de dur&#233;e&quot;&gt;Extension de dur&#233;e&lt;/a&gt;.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONFOCALISATIONDEBASE&quot; href=&quot;#INVOCATIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_18&quot; href=&quot;#Pouvoir_de_focalisation_de_base_18&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments d’invocation acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Serviteur (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour convoquer un serviteur. Ce pouvoir fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-I.html&quot; title=&quot;Convocation de monstres I&quot;&gt;convocation de monstres I&lt;/a&gt;&lt;/i&gt; mais le personnage peut l’utiliser uniquement pour convoquer une unique cr&#233;ature et l’effet dure une minute. Au niveau 4 et tous les 3 niveaux par la suite, le niveau du sort de convocation de monstres augmente de 1, jusqu’&#224; la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Vii.html&quot; title=&quot;Convocation de monstres VII&quot;&gt;convocation de monstres VII&lt;/a&gt;&lt;/i&gt; au maximum au niveau 19. Le personnage ne peut disposer de plus d’un serviteur actif en m&#234;me temps. Il peut d&#233;penser, quand il le souhaite, 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; pour qu’un serviteur d&#233;j&#224; pr&#233;sent puisse rester une minute de plus.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONFOCALISATION&quot; href=&quot;#INVOCATIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_19&quot; href=&quot;#Pouvoirs_de_focalisation_19&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments d’invocation peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Brume psychique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er une nappe de brume. Cette brume reste en place pendant une minute par niveau d’occultiste. Elle fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nappe-De-Brouillard.html&quot; title=&quot;Nappe de brouillard&quot;&gt;nappe de brouillard&lt;/a&gt;&lt;/i&gt; sauf que le vent ne peut pas la disperser. Au niveau 7, le personnage peut d&#233;penser un point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; suppl&#233;mentaire au moment o&#249; il cr&#233;e cette brume pour augmenter sa densit&#233;. Cette brume solidifi&#233;e fonctionne comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brouillard-Dense.html&quot; title=&quot;Brouillard dense&quot;&gt;brouillard dense&lt;/a&gt;&lt;/i&gt; sauf qu’elle ne ralentit pas les cr&#233;atures dot&#233;es de pouvoirs psychiques ou les lanceurs de sorts psychiques. Quand le personnage cr&#233;e un brouillard dense avec ce pouvoir, sa dur&#233;e est r&#233;duite &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Destrier spectral (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour convoquer un destrier spectral. Ce pouvoir peut convoquer un destrier de taille M ou G et fonctionne par ailleurs comme un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monture.html&quot; title=&quot;Monture&quot;&gt;monture&lt;/a&gt;&lt;/i&gt;. Le cheval dispara&#238;t au bout de dix minutes par niveau d’occultiste. Si le personnage est de niveau 5 au moins, la vitesse de d&#233;placement de base au sol de la monture augmente de 6 m&#232;tres. S’il est de niveau 9 au moins et s’il d&#233;pense 1 point de focalisation mentale suppl&#233;mentaire, la monture peut voler &#224; une vitesse de 18 m&#232;tres avec une bonne manœuvrabilit&#233; mais, dans ce cas, elle dispara&#238;t au bout d‘une minute par niveau d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;&#201;puration (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour extirper les maux dont est victime une cr&#233;ature. Le personnage doit toucher la cible avec son instrument pour utiliser ce pouvoir. Celui-ci fonctionne soit comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Neutralisation-Du-Poison.html&quot; title=&quot;Neutralisation du poison&quot;&gt;neutralisation du poison&lt;/a&gt;&lt;/i&gt;, soit comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Des-Maladies.html&quot; title=&quot;Gu&#233;rison des maladies&quot;&gt;gu&#233;rison des maladies&lt;/a&gt;&lt;/i&gt;, en appliquant le niveau d’occultiste du personnage en guise de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;. Chaque utilisation de ce pouvoir peut soigner un seul poison ou une seule maladie. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Gu&#233;rison physique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour soigner une cr&#233;ature vivante d’un simple contact. La cr&#233;ature r&#233;cup&#232;re un nombre de points de vie &#233;gal &#224; 1d8 + le niveau d’occultiste. Pour chaque tranche de 4 niveaux d’occultiste au-del&#224; du troisi&#232;me, la cr&#233;ature r&#233;cup&#232;re 1d8 points de vie suppl&#233;mentaires, jusqu’&#224; un maximum de 5d8+19 au niveau 19. Ce pouvoir ne produit aucun effet sur les morts-vivants. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Invocation d’instrument (Mag)&lt;/i&gt;. Le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour invoquer un objet susceptible de servir d’instrument si le personnage sait l’utiliser. Cet instrument peut &#234;tre utilis&#233; de la m&#234;me fa&#231;on que tous les objets de son type et fonctionne comme une version de qualit&#233; sup&#233;rieure. Le personnage peut &#233;galement l’utiliser pour lancer ses sorts psychiques, m&#234;me s’il ne l’a pas s&#233;lectionn&#233; au d&#233;but de la journ&#233;e. S’il poss&#232;de plus d’un instrument pour la m&#234;me &#233;cole, le personnage d&#233;cide quel ensemble de sorts l’instrument conf&#233;rera lors de sa premi&#232;re invocation. L’instrument ne peut pas &#234;tre utilis&#233; pour stocker de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; ou pour cr&#233;er des effets qui n&#233;cessitent ce type de focalisation. L’instrument dispara&#238;t au bout de dix minutes par niveau d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Pas de c&#244;t&#233; (Mag)&lt;/i&gt;. Le personnage peut ouvrir une fissure temporaire dans l’espace en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. Il peut utiliser ce pouvoir au cours d’une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; effectu&#233;e pour se d&#233;placer. La fissure s’ouvre dans une case d&#233;sign&#233;e par le personnage et lui permet de se t&#233;l&#233;porter vers une autre case qu’il peut voir et situ&#233;e dans un rayon de 3 m&#232;tres par niveau d’occultiste. La t&#233;l&#233;portation entre les deux emplacements n&#233;cessite la d&#233;pense de 1,50 m&#232;tre de d&#233;placement et le d&#233;placement au travers de la fissure ne provoque pas d’attaque d’opportunit&#233;. Ce pouvoir fonctionne par ailleurs comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt;. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DIVINATION&quot; href=&quot;#DIVINATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments de divination&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_de_divination_37&quot; href=&quot;#Instruments_de_divination_37&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments de l’&#233;cole de divination conf&#232;rent des pouvoirs li&#233;s aux pr&#233;visions et &#224; la scrutation &#224; distance.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DIVINATIONINSTRUMENTS&quot; href=&quot;#DIVINATIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_20&quot; href=&quot;#Instruments_20&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Bandeau, boule de cristal, jeu du tourment, lentille de contact, livre, lunettes, planchette d’&#233;criture automatique.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DIVINATIONRESONANCE&quot; href=&quot;#DIVINATIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_21&quot; href=&quot;#Pouvoir_de_r&#233;sonance_21&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument de divination, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Troisi&#232;me oeil (Sur)&lt;/i&gt;. L’instrument permet &#224; son porteur de remarquer les d&#233;tails difficiles &#224; percevoir. Il conf&#232;re un bonus d’intuition de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; par tranche de 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’instrument, jusqu’&#224; un bonus maximal &#233;gal au niveau d’occultiste. Si l’occultiste est de niveau 3 ou plus et investit au moins 3 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans l’instrument, celui-ci conf&#232;re &#233;galement la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;vision nocturne&quot;&gt;vision nocturne&lt;/a&gt;. Si l’occultiste est de niveau 5 ou plus et investit au moins 6 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans l’instrument, celui-ci conf&#232;re &#233;galement la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; jusqu’&#224; 18 m&#232;tres (si le porteur poss&#232;de d&#233;j&#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt;, l’instrument augmente la port&#233;e de celle-ci de 9 m&#232;tres). Si l’occultiste est de niveau 7 ou plus et investit au moins 9 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans l’instrument, celui-ci conf&#232;re &#233;galement les effets d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt;. Si l’occultiste est de niveau 13 ou plus et investit au moins 12 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans l’instrument, celui-ci conf&#232;re &#233;galement la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;vision aveugle&quot;&gt;vision aveugle&lt;/a&gt; jusqu’&#224; 9 m&#232;tres.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DIVINATIONFOCALISATIONDEBASE&quot; href=&quot;#DIVINATIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_22&quot; href=&quot;#Pouvoir_de_focalisation_de_base_22&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments de divination acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Intuition soudaine (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;] pour obtenir un pr&#233;sage de son futur imm&#233;diat. Il peut utiliser ce pr&#233;sage par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; avant d’effectuer un test de caract&#233;ristique, un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; ou un test de comp&#233;tence pour b&#233;n&#233;ficier d’un bonus d’intuition &#233;gal &#224; la moiti&#233; de son niveau d’occultiste (+1 au minimum) sur ce jet. Le personnage ne peut exploiter ce pr&#233;sage qu’une seule fois par tour et il dispara&#238;t en ne conf&#233;rant aucun avantage s’il n’est pas utilis&#233; avant la fin de son prochain tour.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DIVINATIONFOCALISATION&quot; href=&quot;#DIVINATIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_23&quot; href=&quot;#Pouvoirs_de_focalisation_23&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments de divination peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Lien intime (Sur)&lt;/i&gt;. Quand il lance un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Divination.html&quot; title=&quot;Divination&quot;&gt;divination&lt;/a&gt; (tel que &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scrutation.html&quot; title=&quot;Scrutation&quot;&gt;scrutation&lt;/a&gt;&lt;/i&gt;) qui impose un malus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; bas&#233;s sur le rapport physique du personnage avec sa cible, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour doubler le malus li&#233; &#224; une possession mat&#233;rielle, un v&#234;tement ou une partie du corps. En outre, quand il lance un autre sort de l’&#233;cole de divination qui autorise un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;, le personnage peut augmenter le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; de 2 en ajoutant un objet, un v&#234;tement ou une partie du corps qui appartenait &#224; la cible. Cet ajout fait office de composante de focalisation lors de l’incantation du sort si le personnage d&#233;pense 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Œil spirituel (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er un œil spirituel : un capteur magique &#224; travers lequel il peut voir et entendre. Cet oeil est invisible et sa taille est Infime, ce qui lui conf&#232;re une CA de 18. L’œil est d&#233;truit s’il subit le moindre point de d&#233;g&#226;t mais seuls les sorts et les armes magiques peuvent le d&#233;truire. Il se d&#233;place en volant &#224; une vitesse de 18 m&#232;tres avec une manœuvrabilit&#233; parfaite et peut s’&#233;loigner du personnage jusqu’&#224; une distance maximale de 1,5 kilom&#232;tre. Le personnage doit se concentrer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour diriger l’œil et r&#233;ceptionner les images sensorielles par son interm&#233;diaire. L’œil voit avec les m&#234;mes moyens de perception que le personnage, y compris avec les &#233;ventuels sens suppl&#233;mentaires dont il dispose (comme la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; ou la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt;). L’œil spirituel persiste pendant une minute par niveau d’occultiste. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Œil vigilant (Mag)&lt;/i&gt;. Le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour cr&#233;er un capteur invisible &#224; 9 m&#232;tres ou moins qui observe une zone de 1,50 m&#232;tre de c&#244;t&#233;. Chaque fois qu’une cr&#233;ature entre dans cette case, le personnage re&#231;oit une image mentale de celle-ci tant qu’il se trouve sur le m&#234;me plan que le capteur. Ce dernier reste actif pendant dix minutes par niveau d’occultiste. L’image ne r&#233;veille pas le personnage s’il dort mais il re&#231;oit toutes les images collect&#233;es par le capteur d&#232;s son r&#233;veil. Il est possible de d&#233;jouer un capteur gr&#226;ce &#224; l’invisibilit&#233; ou une magie similaire. Le personnage peut d&#233;penser des points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; suppl&#233;mentaires au moment de la cr&#233;ation de l’œil pour augmenter la taille de la zone, &#224; raison de 1,50 m&#232;tre de c&#244;t&#233; par point d&#233;pens&#233; (1 point pour une zone de 3 m&#232;tres de c&#244;t&#233;, 2 points pour une zone de 4,50 m&#232;tres de c&#244;t&#233;, etc.).&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Pr&#233;vision du danger (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, le personnage peut se prot&#233;ger des coups en d&#233;pensant 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;. Il peut utiliser ce pouvoir &#224; chaque fois qu’il est la cible d’une attaque ou doit effectuer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un pouvoir sp&#233;cial, un sort ou un pi&#232;ge. Ce faisant, la pr&#233;vision lui conf&#232;re un bonus d’intuition &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; ou &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son niveau d’occultiste. Ce bonus s’applique uniquement &#224; la prochaine attaque effectu&#233;e contre le personnage ou le prochain &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; qu’il effectue et la protection dispara&#238;t en ne conf&#233;rant aucun avantage si elle n’est pas utilis&#233;e avant la fin du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Scrutation d’un objet (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour obtenir une information intuitive sur un objet en sa possession. Il peut poser une question, mais celle-ci doit avoir un rapport, d’une fa&#231;on ou d’une autre, avec l’objet, telle que la nature de son pouvoir, l’identit&#233; de son dernier propri&#233;taire, voire l’endroit o&#249; &#233;tait l’objet lors du d&#233;roulement d’un &#233;v&#233;nement pr&#233;cis. Le personnage re&#231;oit toujours une r&#233;ponse fournie par les impressions psychiques imprim&#233;es dans l’objet, mais celles-ci sont parfois &#233;nigmatiques ou trompeuses. Ce pouvoir fonctionne par ailleurs comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt;. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Vision de l’avenir (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut obtenir une vision de l’avenir en d&#233;pensant 1 point de focalisation mentale. Ce pouvoir fonctionne comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;augure&lt;/a&gt;&lt;/i&gt; avec le niveau d’occultiste en guise de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NECROMANCIE&quot; href=&quot;#NECROMANCIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments de n&#233;cromancie&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_de_n&#233;cromancie_38&quot; href=&quot;#Instruments_de_n&#233;cromancie_38&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments qui puisent leur pouvoir des &#233;nergies n&#233;cromantiques peuvent contr&#244;ler les morts-vivants et nuire aux vivants.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NECROMANCIEINSTRUMENTS&quot; href=&quot;#NECROMANCIEINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt; 	
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_24&quot; href=&quot;#Instruments_24&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cr&#226;ne, os, pi&#232;ce de monnaie, poup&#233;e, robe, tambour.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NECROMANCIERESONANCE&quot; href=&quot;#NECROMANCIERESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_25&quot; href=&quot;#Pouvoir_de_r&#233;sonance_25&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument de n&#233;cromancie, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Focalisation n&#233;cromantique (Sur)&lt;/i&gt;. L’instrument conf&#232;re &#224; son possesseur un pouvoir plus grand sur les morts-vivants. Quiconque poss&#232;de l’instrument peut contr&#244;ler 2 D&#233;s de Vie suppl&#233;mentaires de morts-vivants pour chaque point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investi dans l’objet (jusqu’&#224; un nombre maximum de D&#233;s de Vie &#233;gal &#224; 4 &#215; le niveau d’occultiste du personnage). Un lanceur de sorts qui porte l’instrument peut l’ajouter en guise de composante de focalisation suppl&#233;mentaire lors de l’incantation d’un sort de n&#233;cromancie lanc&#233; pour cr&#233;er des morts-vivants. Ce faisant, il peut cr&#233;er un nombre de D&#233;s de Vie de morts-vivants suppl&#233;mentaires &#233;gal aux DV suppl&#233;mentaires que l’instrument permet de contr&#244;ler (on applique cet effet apr&#232;s avoir doubl&#233; les DV de morts-vivants dans le cas d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Profanation.html&quot; title=&quot;Profanation&quot;&gt;profanation&lt;/a&gt;&lt;/i&gt;, le cas &#233;ch&#233;ant). Les morts-vivants subissent un malus de -1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les sorts lanc&#233;s par le porteur de l’instrument pour chaque tranche de 4 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’objet.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NECROMANCIEFOCALISATIONDEBASE&quot; href=&quot;#NECROMANCIEFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_26&quot; href=&quot;#Pouvoir_de_focalisation_de_base_26&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments de n&#233;cromancie acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Terreur mentale (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour qu’une cr&#233;ature vivante succombe &#224; la terreur. La cible doit &#234;tre situ&#233;e &#224; 9 m&#232;tres ou moins du personnage et peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler l’effet. Si elle rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; et poss&#232;de un nombre de D&#233;s de Vie inf&#233;rieur ou &#233;gal &#224; celui du personnage, elle est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Effray&#233;.html&quot; title=&quot;Effray&#233;&quot;&gt;effray&#233;e&lt;/a&gt; pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Si elle rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; et poss&#232;de un nombre de D&#233;s de Vie sup&#233;rieur &#224; celui du personnage, elle est simplement &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;e&lt;/a&gt; pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; de terreur.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NECROMANCIEFOCALISATION&quot; href=&quot;#NECROMANCIEFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_27&quot; href=&quot;#Pouvoirs_de_focalisation_27&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments de n&#233;cromancie peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Fl&#233;trissement de la chair (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps et d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour provoquer le pourrissement des chairs d’une cr&#233;ature vivante. Si l’attaque touche sa cible, celle-ci subit 1d8 points de d&#233;g&#226;ts + 1 point par niveau d’occultiste. Pour chaque tranche de 4 niveaux d’occultiste au-del&#224; du 3&#232;me, la cible subit 1d8 points de d&#233;g&#226;ts suppl&#233;mentaires (jusqu’&#224; un maximum de 5d8 au niveau 19). Si le personnage rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps, ce pouvoir est g&#226;ch&#233; et ne produit aucun effet. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Linceul spirituel (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour s’envelopper d’un linceul d’&#233;nergie spirituelle. Il gagne un nombre de points de vie temporaires &#233;gal &#224; 1d6 + son niveau d’occultiste. Ce linceul persiste pendant une minute par niveau d’occultiste ou jusqu’&#224; la disparition de la totalit&#233; des points de vie temporaires, selon ce qui se produit en premier. Ces points de vie temporaires se cumulent avec ceux conf&#233;r&#233;s par d’autres sources mais pas avec ceux obtenus gr&#226;ce &#224; plusieurs utilisations de ce pouvoir. Au niveau 4, tant que le linceul est actif, le personnage b&#233;n&#233;ficie d’un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#MORT&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effets de mort&lt;/a&gt;, de terreur et tous les sorts et les effets qui infligent des niveaux n&#233;gatifs ou des d&#233;g&#226;ts d’&#233;nergie n&#233;gative (si ces sorts ou effets autorisent un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;). Ce bonus est &#233;gal &#224; 1 + 1 tous les 4 niveaux d’occultiste au-del&#224; du 4&#232;me. Le personnage doit avoir atteint le niveau 3 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Mal&#233;diction psychique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour maudire avec sa magie psychique une cr&#233;ature vivante situ&#233;e &#224; 9 m&#232;tres ou moins. Le personnage choisit l’un des effets suivants : trou de m&#233;moire, blocage mental ou confusion par la douleur. S’il choisit le trou de m&#233;moire, la cible oublie tout ce qui s’est pass&#233; sur une p&#233;riode d’une heure par niveau d’occultiste avant l’utilisation de ce pouvoir. S’il choisit le blocage mental, le personnage peut interdire l’accomplissement d’une action sp&#233;cifique, comme l’attaque avec une cat&#233;gorie d’armes, le lancement d’un sort particulier ou une autre action aussi sp&#233;cifique (le MJ a le dernier mot sur ce point). La cible doit d’abord r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour pouvoir entreprendre cette action. En cas d’&#233;chec, elle peut effectuer d’autres actions &#224; la place. Si elle tente l’action interdite &#224; nouveau lors des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; suivants, elle b&#233;n&#233;ficie d’un bonus cumulatif de +2 &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; jusqu’&#224; ce qu’elle le r&#233;ussisse. S’il choisit la confusion par la douleur, la cr&#233;ature est confuse pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; chaque fois qu’elle est la victime d’un coup critique. La cible peut effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour annuler cet effet qui dure un jour par niveau d’occultiste. Une cr&#233;ature ne peut pas &#234;tre la cible de plusieurs effets de mal&#233;diction psychique en m&#234;me temps. C’est un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#EFFETMENTAL&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effet mental&lt;/a&gt; de mal&#233;diction. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Pantin des &#226;mes (Sur)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour cr&#233;er un &lt;a class=&quot;pagelink&quot; href=&quot;Pantin-Des-&#194;mes.html&quot; title=&quot;Pantin des &#226;mes&quot;&gt;pantin des &#226;mes&lt;/a&gt; avec un os, une poup&#233;e ou un cr&#226;ne. S’il utilise un os ou un cr&#226;ne, l’utilisation de ce pouvoir l’enveloppe de chair pour cr&#233;er un pantin de taille P ou TP qui ressemble vaguement &#224; la cr&#233;ature &#224; laquelle appartenait l’os ou la cr&#226;ne. Si l’instrument est une poup&#233;e, celle-ci prend vie. Consid&#233;rez cette cr&#233;ature comme un familier en appliquant le niveau d’occultiste &#224; la place du niveau de magicien pour d&#233;terminer ses pouvoirs et ses aptitudes. Le personnage peut donner vie &#224; un familier pr&#233;cis s’il utilise l’os ou le cr&#226;ne d’une cr&#233;ature correspondante ou une poup&#233;e qui ressemble &#224; ce familier. Sinon, le personnage peut utiliser l’os, le cr&#226;ne ou une poup&#233;e en forme d’humano&#239;de pour conf&#233;rer au pantin le profil de base d’un &lt;a class=&quot;pagelink&quot; href=&quot;Homoncule.html&quot; title=&quot;Homoncule&quot;&gt;homoncule&lt;/a&gt; mais sans le pouvoir sp&#233;cial de lien t&#233;l&#233;pathique et sans la morsure empoisonn&#233;e ni la vitesse de d&#233;placement en vol. Quelle que soit sa forme, cette cr&#233;ature est une &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Artificielle.html&quot; title=&quot;Cr&#233;ature artificielle&quot;&gt;cr&#233;ature artificielle&lt;/a&gt; dont l’alignement est identique &#224; celui du personnage. Le personnage ne peut poss&#233;der plus d’un &lt;a class=&quot;pagelink&quot; href=&quot;Pantin-Des-&#194;mes.html&quot; title=&quot;Pantin des &#226;mes&quot;&gt;pantin des &#226;mes&lt;/a&gt; anim&#233; en m&#234;me temps. Celui-ci reste anim&#233; pendant dix minutes par niveau d’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Serviteur n&#233;cromantique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour relever un &lt;a class=&quot;pagelink&quot; href=&quot;Squelette-Humain.html&quot; title=&quot;Squelette, Squelette humain&quot;&gt;squelette humain&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Zombi-Humain.html&quot; title=&quot;Zombi, Zombi humain&quot;&gt;zombi humain&lt;/a&gt; afin qu’il le serve pendant dix minutes par niveau d’occultiste ou jusqu’&#224; sa destruction, selon ce qui se produit en premier. Ce serviteur poss&#232;de un nombre de points de vie &#233;gal &#224; la moiti&#233; du total maximum de points de vie du personnage (ce nombre n’est pas modifi&#233; par l’ajout de points de vie temporaires ou autres augmentations temporaires). Il est &#233;galement dot&#233; du bonus de base &#224; l’attaque du personnage et b&#233;n&#233;ficie d’un bonus aux jets de d&#233;g&#226;ts &#233;gal &#224; la moiti&#233; du niveau d’occultiste du personnage. Au niveau 5, au moment o&#249; le serviteur n&#233;cromantique devrait &#234;tre d&#233;truit et s’il se trouve &#224; port&#233;e moyenne du personnage ou moins (30 m&#232;tres + 3 m&#232;tres par niveau), l’occultiste peut d&#233;penser 1 point de focalisation mentale par une action imm&#233;diate pour que le serviteur r&#233;cup&#232;re la totalit&#233; de ses points de vie. Au niveau 9, il peut d&#233;cider d’affubler son squelette de l’arch&#233;type simple &lt;a class=&quot;pagelink&quot; href=&quot;Squelette,-Arch&#233;type-.html&quot; title=&quot;Squelette, arch&#233;type&quot;&gt;sanglant&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Squelette,-Arch&#233;type.html&quot; title=&quot;Squelette, arch&#233;type&quot;&gt;br&#251;lant&lt;/a&gt; ou son zombi de l’arch&#233;type simple &lt;a class=&quot;pagelink&quot; href=&quot;Zombi,-Arch&#233;type.html&quot; title=&quot;Zombi, arch&#233;type&quot;&gt;rapide&lt;/a&gt;. Au niveau 13, quand le personnage effectue une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; pour soigner son serviteur, celui-ci se divise en deux serviteurs. Le personnage peut avoir un nombre maximum de serviteurs actifs &#233;gal &#224; la moiti&#233; de son niveau d’occultiste. Au niveau 17, le serviteur obtient un don de travail en &#233;quipe au choix de l’occultiste.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Vague de douleur (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour produire une vague de douleur. Cette vague frappe toutes les cr&#233;atures &#224; l’exception du personnage dans un rayonnement de 6 m&#232;tres de rayon centr&#233; sur un point situ&#233; &#224; 30 m&#232;tres ou moins du personnage. Toutes les cr&#233;atures vivantes pr&#233;sentes dans la zone ressentent une douleur atroce qui les rend &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuses&lt;/a&gt; pendant un round par niveau d’occultiste. Les cr&#233;atures affect&#233;es peuvent effectuer un jet de Volont&#233; pour r&#233;duire la dur&#233;e &#224; un round seulement. C’est un effet mental de douleur. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRANSMUTATION&quot; href=&quot;#TRANSMUTATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Instruments de transmutation&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_de_transmutation_39&quot; href=&quot;#Instruments_de_transmutation_39&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les instruments de transmutation peuvent modifier les propri&#233;t&#233;s intrins&#232;ques des objets et des cr&#233;atures.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRANSMUTATIONINSTRUMENTS&quot; href=&quot;#TRANSMUTATIONINSTRUMENTS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Instruments&lt;a class=&quot;headeranchor&quot; id=&quot;Instruments_28&quot; href=&quot;#Instruments_28&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Arme, botte, ceinture, gilet, sandale.
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRANSMUTATIONRESONANCE&quot; href=&quot;#TRANSMUTATIONRESONANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de r&#233;sonance&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_r&#233;sonance_29&quot; href=&quot;#Pouvoir_de_r&#233;sonance_29&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois que l’occultiste investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans un instrument de transmutation, l’objet conf&#232;re le pouvoir de r&#233;sonance suivant. Le porteur de l’instrument b&#233;n&#233;ficie des avantages de ce pouvoir jusqu’au moment o&#249; l’occultiste r&#233;cup&#232;re sa focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Am&#233;lioration physique (Sur)&lt;/i&gt;. L’instrument am&#233;liore les capacit&#233;s physiques de son porteur. Le personnage choisit une caract&#233;ristique physique quand il investit de la &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; dans l’instrument. Celui-ci conf&#232;re un bonus d’alt&#233;ration temporaire de +2 &#224; cette valeur de caract&#233;ristique tous les 3 points de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; investis dans l’instrument (jusqu’&#224; un maximum de +2 au niveau 1, et +2 suppl&#233;mentaires tous les 6 niveaux d’occultiste).&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRANSMUTATIONFOCALISATIONDEBASE&quot; href=&quot;#TRANSMUTATIONFOCALISATIONDEBASE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoir de focalisation de base&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoir_de_focalisation_de_base_30&quot; href=&quot;#Pouvoir_de_focalisation_de_base_30&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Tous les occultistes qui apprennent l’utilisation des instruments de transmutation acqui&#232;rent le pouvoir de focalisation suivant.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Arme parrain&#233;e (Sur)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; et toucher une arme pour lui conf&#233;rer un bonus d’alt&#233;ration. Ce bonus est &#233;gal &#224; 1 + 1 tous les 6 niveaux d’occultiste (jusqu’&#224; un bonus maximum de +4 au niveau 18). Les bonus d’alt&#233;ration obtenus gr&#226;ce &#224; ce pouvoir se cumulent avec ceux de l’arme, jusqu’&#224; un total maximum de +5. Le personnage peut &#233;galement conf&#233;rer &#224; l’arme une propri&#233;t&#233; sp&#233;ciale d’arme dont l’&#233;quivalent pour le bonus d’alt&#233;ration est inf&#233;rieur ou &#233;gal au bonus maximal que le personnage peut conf&#233;rer &#224; l’arme. Ce faisant, il diminue le bonus d’alt&#233;ration conf&#233;r&#233; du montant de la propri&#233;t&#233; sp&#233;ciale. L’objet doit poss&#233;der un bonus d’alt&#233;ration de +1 au moins (ce bonus doit provenir de l’objet lui-m&#234;me ou de l’arme parrain&#233;e) pour pouvoir b&#233;n&#233;ficier d’une propri&#233;t&#233; sp&#233;ciale d’arme. Ces bonus et l’&#233;ventuelle propri&#233;t&#233; sp&#233;ciale durent une minute.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRANSMUTATIONFOCALISATION&quot; href=&quot;#TRANSMUTATIONFOCALISATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de focalisation&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_focalisation_31&quot; href=&quot;#Pouvoirs_de_focalisation_31&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En plus du pouvoir de focalisation de base, les occultistes qui apprennent l’utilisation des instruments de transmutation peuvent s&#233;lectionner les pouvoirs de focalisation suivants lorsqu’ils choisissent ceux conf&#233;r&#233;s par leur aptitude de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#POUVOIRSDEFOCALISATION&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;pouvoirs de focalisation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;C&#233;l&#233;rit&#233; soudaine (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le personnage peut d&#233;penser 1 point de focalisation mentale pour augmenter brusquement sa vitesse de d&#233;placement. Sa vitesse de d&#233;placement augmente alors de 9 m&#232;tres pendant une minute. L’effet de ce pouvoir ne se cumule pas avec lui-m&#234;me.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Changement de taille (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; et toucher une cr&#233;ature pour changer sa taille. Le personnage peut augmenter ou diminuer la taille de la cr&#233;ature touch&#233;e d’une cat&#233;gorie, comme avec un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt; ou un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapetissement.html&quot; title=&quot;Rapetissement&quot;&gt;rapetissement&lt;/a&gt;&lt;/i&gt;, mais sans la restriction impos&#233;e par le type de la cr&#233;ature. Si la cr&#233;ature est hostile envers le personnage, l’utilisation de ce pouvoir n&#233;cessite la r&#233;ussite d’une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUESDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps et la cr&#233;ature peut effectuer un jet de Vigueur pour annuler l’effet. Cet effet dure un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage ne peut pas utiliser ce pouvoir sur une cr&#233;ature d&#233;j&#224; affect&#233;e par un effet qui modifie sa taille.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Contact philosophal (Sur)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; et toucher une arme pour lui conf&#233;rer les propri&#233;t&#233;s d’un &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;mat&#233;riau sp&#233;cial&lt;/a&gt;. L’arme est alors consid&#233;r&#233;e comme une arme en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Ferfroid.html&quot; title=&quot;fer froid&quot;&gt;fer froid&lt;/a&gt; ou en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Argent.html&quot; title=&quot;argent&quot;&gt;argent&lt;/a&gt; lorsqu’il s’agit d’ignorer la r&#233;duction des d&#233;g&#226;ts et ce, pendant 1 minute par niveau d’occultiste. Au niveau 4 et tous les 4 niveaux par la suite, le personnage peut toucher une arme suppl&#233;mentaire lorsqu’il utilise ce pouvoir pour lui conf&#233;rer le m&#234;me avantage (toujours en d&#233;pensant 1 seul point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;). Au niveau 11, toutes les armes affect&#233;es par ce pouvoir sont consid&#233;r&#233;es comme des armes en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Adamantium.html&quot; title=&quot;adamantium&quot;&gt;adamantium&lt;/a&gt; (mais uniquement pour ignorer la r&#233;duction des d&#233;g&#226;ts et non la solidit&#233;).&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Domination de l’esprit sur la gravit&#233; (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour obtenir une vitesse de d&#233;placement en vol de 18 m&#232;tres avec une manœuvrabilit&#233; parfaite. Cet effet dure une minute par niveau d’occultiste. Le personnage doit avoir atteint le niveau 7 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Ma&#238;trise t&#233;l&#233;kin&#233;sique (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour d&#233;velopper des talents t&#233;l&#233;kin&#233;siques temporaires. Ce pouvoir fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;kin&#233;sie.html&quot; title=&quot;T&#233;l&#233;kin&#233;sie&quot;&gt;t&#233;l&#233;kin&#233;sie&lt;/a&gt;&lt;/i&gt;, sauf que le personnage n’a pas besoin de se concentrer pour maintenir l’effet. De plus, l’utilisation de l’un des effets de ce sort n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Cet effet dure une minute par niveau d’occultiste. Le personnage doit avoir atteint le niveau 9 au moins avant de pouvoir choisir ce pouvoir de focalisation.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Rapidit&#233; (Mag)&lt;/i&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le personnage peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; pour augmenter de mani&#232;re surnaturelle sa rapidit&#233; et ses r&#233;flexes, ou bien ceux d’une cr&#233;ature vivante et consentante qu’il touche. Ce pouvoir fonctionne comme une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt; sauf que le bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et aux jets de R&#233;flexes s’&#233;l&#232;vent &#224; +2. Cet effet dure un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d’occultiste. Le personnage doit avoir atteint le niveau 5 au moins avant de pouvoir choisir ce pouvoir de focalisation.
